&lt;ul class=&quot;pb-2 flex flex-col gap-1 list-disc pl-6 text-foreground text-base leading-relaxed&quot;&gt;
&lt;li class=&quot;break-words text-foreground text-base leading-relaxed&quot;&gt;CDI&lt;/li&gt;
&lt;li class=&quot;break-words text-foreground text-base leading-relaxed&quot;&gt;Temps Plein&lt;/li&gt;
&lt;li class=&quot;break-words text-foreground text-base leading-relaxed&quot;&gt;Paris / Île-de-France&lt;/li&gt;
&lt;li class=&quot;break-words text-foreground text-base leading-relaxed&quot;&gt;Prise de poste : dès que possible&lt;/li&gt;
&lt;li class=&quot;break-words text-foreground text-base leading-relaxed&quot;&gt;Rémunération : fixe + variable&lt;/li&gt;
