&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Location:&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt; Frankfurt, Düsseldorf, Berlin, München (Hybrid) | &lt;/span&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Practice Area:&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt; Finance, Risk, Regulatory &amp;amp; Financial Crime | &lt;/span&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Type:&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt; Permanent&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Gestalte mit uns die digitale und operationale Resilienz von Finanzinstituten – von DORA und IKT-Risikomanagement bis hin zu Third Party Risk und Operational Resilience.&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Die Rolle&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Als (Senior) Consultant* – Operational &amp;amp; Cyber Resilience unterstützt Du unsere Kundinnen und Kunden aus der Finanzindustrie bei der Umsetzung regulatorischer Anforderungen, insbesondere rund um den Digital Operational Resilience Act (DORA) und den einschlägigen EBA Guidelines. Du arbeitest an der Schnittstelle von Regulatorik, IKT-Risikomanagement, Operational Resilience und IT Governance und begleitest unsere Kunden von der Analyse bestehender Strukturen bis zur nachhaltigen Umsetzung.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Dabei beschäftigst Du Dich unter anderem mit IKT-Kontrollframeworks, Incident Management, Third Party Risk Management sowie Auslagerungsmanagement. &lt;/span&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Du nutzt zudem freigegebene AI-Tools, Automatisierung und AI-enabled Workflows dort, wo sie Analysen, Qualität und Produktivität sinnvoll verbessern – stets unter Berücksichtigung menschlicher Beurteilung, angemessener Kontrollen und Responsible-AI-Vorgaben.&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Deine Aufgaben&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Berate Finanzinstitute bei der &lt;/span&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Umsetzung und Weiterentwicklung von DORA-Anforderungen&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt; sowie beim Aufbau einer nachhaltigen Digital Operational Resilience.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Analysiere und optimiere &lt;/span&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;IKT-/IT-Risikomanagement, IT Governance sowie IKT-/IT-Kontrollframeworks&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt; und unterstütze bei der Entwicklung geeigneter Governance- und Kontrollstrukturen.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Unterstütze bei &lt;/span&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Third Party Risk Management, ICT Third Party Risk, IT Supplier Risk und Auslagerungsmanagement&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt; – von Risikoanalysen bis zur Implementierung belastbarer Steuerungsprozesse.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Begleite unsere Kunden bei &lt;/span&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;ICT Incident Management und Major ICT Incidents&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;, einschließlich der Weiterentwicklung relevanter Prozesse, Kontrollen und regulatorischer Anforderungen.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Nutze freigegebene AI- und Automatisierungslösungen&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;, um beispielsweise Analysen, Dokumentation und Kontrollaktivitäten effizienter zu gestalten, und stelle dabei Human-in-the-Loop-Prüfung, nachvollziehbare Ergebnisse und erforderliche Eskalationswege sicher.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Dein Profil&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Erfahrung oder fundierte Kenntnisse im Bereich &lt;/span&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;DORA, IKT-/IT-Risikomanagement, Operational Resilience oder Operational Risk&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;, idealerweise im Finanzdienstleistungsumfeld.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Kenntnisse in mindestens einem weiteren relevanten Themenfeld wie &lt;/span&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;IT Governance, ICT Controls, Incident Management, Third Party Risk Management oder Auslagerungsmanagement&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
